export interface TeacherClassToday {
  classId: number;
  className: string;
  gradeLevel: number;
  subjectName: string;
  /**
     * Null for an administrator's card, which stands for the whole class rather than one subject. Carried so a link from this card can open the timetable or the results on the subject the card is about, instead of dropping the reader on whatever the page picks first.
     * @nullable
     */
  subjectId: number | null;
  /**
     * The proficiency ladder this subject uses, or null where it uses none.
     * @nullable
     */
  levelFramework: string | null;
  /** @nullable */
  lessonCode: string | null;
  /** @nullable */
  skillName: string | null;
  /** @nullable */
  pageFrom: number | null;
  /** @nullable */
  pageTo: number | null;
  studentCount: number;
  answeredToday: number;
  attention: AttentionRow[];
}

/**
 * Organised by class rather than by teacher. A teacher holds several classes and often more than one subject, so totals across all of them answer no question anybody asks.
 */
export interface TeacherDashboard {
  teacherName: string;
  dateLabel: string;
  classes: TeacherClassToday[];
}

/**
 * One entry in the teacher's class picker. A teacher who holds two subjects in a class gets one entry per subject plus one for all of them, so id alone no longer identifies an entry - the pair (id, subjectId) does.
 */
export interface TeacherClass {
  id: string;
  name: string;
  gradeLevel: number;
  /** The subject this entry stands for, or null for every subject the teacher may look at in the class. */
  subjectId: number | null;
  /** Whether this account may change what this entry shows - timetable it, mark it, assign it. A class teacher sees subjects somebody else takes; those entries come back read-only. */
  canEdit: boolean;
  subject: string;
  studentCount: number;
  currentTopic: string;
  needsReview: number;
}

